-- Resources content for the Bookings Rates navigation change (CLAUDE.md,
-- "Resources stay in step with the code"). Content only; no schema. The rate
-- model guide is rewritten where the screens changed.

select private.rc_release_guide(
  p_slug => 'bookings-rate-model',
  p_tool_key => 'bookings',
  p_title => 'The rate model',
  p_summary => 'The rate card, the Inputs checklist, labor classes and pools, service packages, and adopting a version.',
  p_screen_keys => array['bookings.rates'],
  p_sort_order => 10,
  p_version_note => 'Rates tabs reduced to Rate card, Inputs and History',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Rates","marks":[{"type":"bold"}]},{"type":"text","text":" tab holds the production rate model: what each class of labor costs an hour, what a studio half-day, an event webcast, a field day or an editing hour costs WUWF, and the rates on the card a partner sees. Everything on the card is computed from the figures; nothing is typed in by hand."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Finding your way"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rate card","marks":[{"type":"bold"}]},{"type":"text","text":" is where Rates opens: the rates a partner sees, computed from the figures."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inputs","marks":[{"type":"bold"}]},{"type":"text","text":" is a checklist of the four pages that feed the card — Assumptions, Labor, Resource pools and Service packages — with how many of each are validated. Select a row to open its page; "},{"type":"text","text":"← Inputs","marks":[{"type":"bold"}]},{"type":"text","text":" returns to the list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" is the change log. Assets is under the "},{"type":"text","text":"⋯","marks":[{"type":"bold"}]},{"type":"text","text":" menu at the end of the row."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Classes and pools"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manage labor classes","marks":[{"type":"bold"}]},{"type":"text","text":" on the Labor page, and "},{"type":"text","text":"Manage resource pools","marks":[{"type":"bold"}]},{"type":"text","text":" on the Resource pools page, list the two things the model is built from. A "},{"type":"text","text":"labor class","marks":[{"type":"bold"}]},{"type":"text","text":" is a kind of production staff — the production lead, student and OPS crew, later a second producer or an engineer — paid by salary or by the hour, and either charged in a strategic price (students) or baseline-funded (professionals)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"pool","marks":[{"type":"bold"}]},{"type":"text","text":" is something that can be booked — studio, field package, live package, edit suite, webcast operations — with its unit and how it is costed: a share of the shared production pool, or its own budget lines. Finance or the Director of Operations adds a class or a pool here; nothing is deleted, only retired."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new class needs its pay figures on each draft version (the "},{"type":"text","text":"Labor","marks":[{"type":"bold"}]},{"type":"text","text":" page), and a new pool its figures on each draft version (the "},{"type":"text","text":"Resource pools","marks":[{"type":"bold"}]},{"type":"text","text":" page) and a resource on the term plan."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The version picker at the top switches between versions. One version is "},{"type":"text","text":"in use","marks":[{"type":"bold"}]},{"type":"text","text":" for estimates at a time. A version that has not been adopted is labelled provisional, and so is every figure from it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An adopted version never changes. To correct it, Finance selects "},{"type":"text","text":"New version","marks":[{"type":"bold"}]},{"type":"text","text":", which copies the chosen version's figures and packages into a draft."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Assumptions, labor and resource pools"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assumptions","marks":[{"type":"bold"}]},{"type":"text","text":" holds the budget lines — the shared production pool's, and the webcasting pool's own — and the two working inputs the math reads directly: the external margin and the university assessment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Labor","marks":[{"type":"bold"}]},{"type":"text","text":" holds each class's pay figures on this version: salary and paid hours or hourly wage, the fringe or payroll load, and the external planning rate. The loaded hourly cost is recomputed from them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource pools","marks":[{"type":"bold"}]},{"type":"text","text":" holds each pool's share of the shared pool (or its own lines) and its available units a year. Cost per unit is the pool's annual cost divided by its units."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every row names who must validate it and what that takes. Finance selects "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" to change a figure on a draft, and "},{"type":"text","text":"Validated","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Accept as is","marks":[{"type":"bold"}]},{"type":"text","text":" to resolve it. "},{"type":"text","text":"What moves the price most","marks":[{"type":"bold"}]},{"type":"text","text":" re-runs the model with one figure moved."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Service packages and the rate card"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"service package","marks":[{"type":"bold"}]},{"type":"text","text":" states its hours per labor class and its units per pool, plus the external market floor. Strategic cost is resource units plus the hours of every class charged in a strategic price; incremental cost adds the other classes' hours at their loaded rate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every rate rounds up to the next $25. The external rate is the higher of the incremental cost grossed up for the margin and the assessment, and the package's market floor. The card lists one labor line per class."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record for estimates","marks":[{"type":"bold"}]},{"type":"text","text":" saves the card as computed, so an estimate priced later keeps the rate it was priced at. "},{"type":"text","text":"Print","marks":[{"type":"bold"}]},{"type":"text","text":" prints the card alone."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Adopting a version"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Finance resolves every assumption, labor figure and pool, then selects "},{"type":"text","text":"Submit for validation","marks":[{"type":"bold"}]},{"type":"text","text":". A version with anything still pending cannot be submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Executive Director selects "},{"type":"text","text":"Adopt","marks":[{"type":"bold"}]},{"type":"text","text":", recording the Budget/Controller's destination index for recoveries. The previous adopted version is superseded, and the new one is in use."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" lists who changed what on each version."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-07-bookings-rates-navigation',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-07',
  p_title => 'Bookings: fewer tabs and panels, shown when needed',
  p_guide_slugs => array['bookings-rate-model'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rates now opens on the Rate card. The four pages that feed it are listed on a new Inputs tab, with how many of each are validated, and the change log is History. Assets is under the ⋯ menu, and the labor class and pool catalogs, formerly Setup, are now managed on the Labor and Resource pools pages. The version banner appears only while a version needs attention. On the Calendar, capacity and airtime fold into a one-line summary and the less common actions are under More. The Dashboard leads with what needs your action, and a request's agreement and owner are folded away until you open them."}]}]}$body$
);
